import React from "react";
import ProfessionalCard from "../components/ProfessionalCard";
import "./Hire.css";

export default function Hire() {
  const professionals = [
    { name: "Rahul Singh", skill: "Electrician", img: "https://via.placeholder.com/200x150?text=Rahul+Singh" },
    { name: "Amit Kumar", skill: "Plumber", img: "https://via.placeholder.com/200x150?text=Amit+Kumar" },
    { name: "Sneha Jain", skill: "Cleaner", img: "https://via.placeholder.com/200x150?text=Sneha+Jain" },
    { name: "Anita Sharma", skill: "House Painter", img: "https://via.placeholder.com/200x150?text=Anita+Sharma" },
    { name: "Vikram Reddy", skill: "Appliance Repair", img: "https://via.placeholder.com/200x150?text=Vikram+Reddy" },
    { name: "Priya Verma", skill: "Gardener", img: "https://via.placeholder.com/200x150?text=Priya+Verma" }
  ];

  return (
    <div className="page">
      <h1>Hire Professionals</h1>

      <div className="pro-grid">
        {professionals.map((pro, index) => (
          <div key={index} className="pro-card">
            <ProfessionalCard name={pro.name} skill={pro.skill} img={pro.img} />
            <button className="hire-btn">Hire</button>
          </div>
        ))}
      </div>
    </div>
  );
}
